    TRUE,
    $j$[{"category": "kitas_permits", "item_key": "E30A Education Visa (1 Year)"}, {"category": "kitas_permits", "item_key": "E30A Education Visa (2 Years)"}]$j$::jsonb,
    'MULTIPLE',
    'REQUIRED',
    NULL,
